theorem modulus_of_posDef_bound {n : ℕ} (hn : 0 < n) {H : Matrix (Fin n) (Fin n) ℝ}
    (hpd : PosDefQ H) :
    ∃ μ : ℝ, 0 < μ ∧ ∀ v : EuclideanSpace ℝ (Fin n), μ * normSq v ≤ quadForm H v

lemma hasFDerivAt_fderiv_of_contDiffAt {f : (Fin n → ℝ) → ℝ} {x : Fin n → ℝ}
    (hf : ContDiffAt ℝ 2 f x) :
    HasFDerivAt (fderiv ℝ f) (fderiv ℝ (fderiv ℝ f) x) x

theorem path_second_deriv_eq {f : (Fin n → ℝ) → ℝ} {x : Fin n → ℝ}
    (hf : ContDiffAt ℝ 2 f x) (v : Fin n → ℝ) :
    deriv (deriv (path f x v)) 0 = fderiv ℝ (fderiv ℝ f) x v v

theorem path_second_deriv_eq_quadForm {f : (Fin n → ℝ) → ℝ} {x : Fin n → ℝ}
    (hf : ContDiffAt ℝ 2 f x) (v : Fin n → ℝ) :
    deriv (deriv (path f x v)) 0 = quadForm (hessianMat f x) v

theorem hessianMat_symm {f : (Fin n → ℝ) → ℝ} {x : Fin n → ℝ}
    (hf : ContDiffAt ℝ 2 f x) (i j : Fin n) :
    hessianMat f x i j = hessianMat f x j i

theorem strong_convex_unique_min {f g : ℝ → ℝ} {μ : ℝ} (hμ : 0 < μ)
    (hSC : StrongConvex μ f g) {xstar : ℝ} (hg0 : g xstar = 0) {x : ℝ}
    (hx : f x = f xstar) : x = xstar

theorem sq_localMin_dichotomy {f : E → ℝ} {f' : E →L[ℝ] ℝ} {x : E}
    (hderiv : HasFDerivAt f f' x) (hmin : IsLocalMin (fun y => f y ^ 2) x) :
    f x = 0 ∨ f' = 0

theorem rip_constant_ge_one_of_nonzero_null {m n : ℕ} (A : SensingMatrix m n) (k : ℕ)
    (delta : ℝ) (hRIP : IsRIP A (2 * k) delta) {z : Fin n → ℝ}
    (hz : IsKSparse (2 * k) z) (hznz : z ≠ 0) (hAz : matVec A z = 0) : 1 ≤ delta

theorem rip_error_bound {m n : ℕ} (A : SensingMatrix m n) (k : ℕ) (delta : ℝ)
    (hRIP : IsRIP A (2 * k) delta) (hdelta : delta < 1) {x xhat : Fin n → ℝ}
    (hx : IsKSparse k x) (hxhat : IsKSparse k xhat) {y e : Fin m → ℝ}
    (hAx : matVec A x = y) (hAxhat : matVec A xhat = y + e) :
    sqNorm (fun j => x j - xhat j) ≤ sqNorm e / (1 - delta)

theorem rip_exact_recovery {m n : ℕ} (A : SensingMatrix m n) (k : ℕ) (delta : ℝ)
    (hRIP : IsRIP A (2 * k) delta) (hdelta : delta < 1) {x xhat : Fin n → ℝ}
    (hx : IsKSparse k x) (hxhat : IsKSparse k xhat) {y : Fin m → ℝ}
    (hAx : matVec A x = y) (hAxhat : matVec A xhat = y) : x = xhat

theorem rip_injective_on_sparse {m n : ℕ} (A : SensingMatrix m n) (k : ℕ) (delta : ℝ)
    (hRIP : IsRIP A (2 * k) delta) (hdelta : delta < 1) :
    Set.InjOn (matVec A) {x : Fin n → ℝ | IsKSparse k x}
